import {requestCard} from './community-ui.js';
import {jointProjectCard} from './camp-living-ui.js';
import {villageLifeSummary} from './village-life.js';
import * as G from './survival.js';
import {VILLAGES,VILLAGE_TECH,villageTechReason,guideGoal,guideStage} from './settlements.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bag=b=>Object.entries(b).map(([id,n])=>G.ITEMS[id].name+' ×'+n).join('、');
const button=(action,id,text,value='',disabled=false)=>`<button class="secondary" data-village-action="${action}" data-village-id="${id}" data-value="${value}" ${disabled?'disabled':''}>${text}</button>`;
export function renderPrologue(s){const scenes=[['岸边醒来','风把陌生的树影推过沙地。你不记得如何来到这里，只听见远处有人敲了三下木头。','先捡起身边的树枝和燧石。世界在你阅读时暂停。'],['先留下一团火','守岸人的话写在漂来的木板上：「别急着问星星在哪里。今晚，先把火照顾好。」','石斧 → 木材和石料 → 营火 → 食物 → 第一夜。之后再认识聚落与科技。'],['从一个人，到一片文明','那三下敲击是问候。河湾有人交换食物，石脊有人修复机器，星苇有人保存种子。','你可以帮助、交换、修复，也可以选择战术挑战。文明的九级，始于第一件共同完成的小事。']];const [title,text,tip]=scenes[Math.min(2,s.settlements.intro)];return{title,body:`<div class="prologue-scene"><div class="prologue-symbol">${['☾','♨','Ⅸ'][s.settlements.intro]}</div><p>${text}</p><p class="subtle">${tip}</p><small>${s.settlements.intro+1} / 3 · 随时可在菜单重看</small></div>${button('intro','',s.settlements.intro===2?'拾起第一根树枝':'继续听下去')}${button('skip','','熟悉玩法，直接进入')}`};}
export function renderVillages(s,selected){const e=s.settlements,id=Object.hasOwn(VILLAGES,selected?.replace('village-',''))?selected.replace('village-',''):'bay',d=VILLAGES[id],v=e.villages[id],n=s.nodes.find(n=>n.id==='village-'+id),near=G.inHome(s)&&n&&G.distance(n,s.player)<150&&s.level>=d.level;
 let body=`<nav class="co-tabs">${Object.entries(VILLAGES).map(([id,d])=>`<button data-village-tab="${id}">${d.name} · ${d.level}级</button>`).join('')}</nav><article class="co-card"><h3>${d.npc}</h3><p>「${d.intro}」</p><p>居民 ${v.population}/10 · 好感 ${v.affinity}/100 · 安稳 ${v.comfort}/100<br>公共食物 ${v.food} · 燃料 ${v.fuel} · 今日交换 ${v.trades}/3</p><p>居民日程：${villageLifeSummary(s,id)}。白天劳作、闲逛与交谈，雨夜回屋。点击聚落标牌交谈，不用追着居民跑。</p><p>${near?'可以当面交谈。':'先到聚落和当地居民交谈；面板里的物资不会远程交付。'}</p>${n&&s.level>=d.level?`<button data-co-walk="${n.id}">前往${d.name}</button>`:''}<button class="primary" data-country="visit" data-country-id="${id}" ${near?'':'disabled'}>走进聚落 · 火屋、工坊与种子屋</button></article>`;
 body+=requestCard(s,id)+jointProjectCard(s,id);
 if(e.lesson<3)body+=`<article class="co-card"><h3>先做一遍小演练 · ${e.lesson}/3</h3><p>${['① 交换：看清拿出什么、得到什么。演练只讲解，不扣物资。','② 委托：先接受，再带物资回到同一位居民处交付。','③ 守望：三格棋盘里的红格是下一轮危险；移动、出手和格挡都会推进一轮。'][e.lesson]}</p>${button('lesson',id,'听懂了，继续','',!near)}</article>`;
 body+=`<div class="co-grid"><article class="co-card"><h3>以物易物</h3><p>你提供：${bag(d.want)}<br>居民提供：${bag(d.gift)}<br>每地每天 3 份库存，好感 +2。先掌握公平交换。</p>${button('trade',id,'确认交换','',!near||!e.tech.includes('barter')||v.trades>=3)}</article><article class="co-card"><h3>${d.quest.name}</h3><p>${d.quest.text}</p><p>交付：${bag(d.quest.cost)}<br>回礼：${bag(d.quest.reward)} · 洞见 +3 · 好感 +15</p>${button(e.active===id?'deliver':'accept',id,v.quest?'✓ 已完成':e.active===id?'交付物资':'接受委托','',!near||v.quest||e.lesson<2||!!e.active&&e.active!==id)}${e.active&&e.active!==id?'<p>当前正在完成'+VILLAGES[e.active].name+'的委托。</p>':''}</article><article class="co-card"><h3>公共生活与居民</h3><p>投入 3 浆果＋3 木材，公共食物和燃料各 +6。世界在原岛运行时，每天使用约每 3 人 1 食物、1 燃料；高好感与安稳会吸引新居民，最多 10 人。缺料只降低安稳，不会杀死居民，不离线产出。</p>${button('supply',id,'补充公共储备','',!near||!e.tech.includes('care'))}</article></div>`;
 const b=e.encounter;if(b&&b.village!==id)body+=`<p>有一场${VILLAGES[b.village].name}的事件尚未结束，请切回该聚落。</p>`;
 else if(b)body+=`<article class="co-card"><h3>${b.practice?'免费守望演练':'失控巡械据点'}</h3><p>队伍耐久 ${b.hp} · 巡械耐久 ${b.enemy} · 第 ${b.turn+1} 轮<br>预警将在每次行动后结算；演练和战斗失败都不扣角色生命。</p><div class="tactical-board">${[0,1,2].map(i=>`<button data-village-action="move" data-village-id="${id}" data-value="${i}" ${i===b.position?'disabled':''} class="${i===b.warning?'warning':''}" aria-label="${['左','中','右'][i]}格${i===b.warning?'，下轮危险':''}"><b>${['左','中','右'][i]}</b><span>${i===b.enemyLane?'⚙ 巡械':'　'}</span><span>${i===b.position?'♜ 你':'　'}</span><small>${i===b.warning?'下一轮危险':'安全位置'}</small></button>`).join('')}</div><p>${b.log}</p>${button('strike',id,'出手（只命中同格）','',!near)}${button('guard',id,'原地格挡本轮','',!near)}${button('retreat',id,'退出事件','',!near)}</article>`;
 else body+=`<article class="co-card"><h3>据点小仗 · 修复或守望</h3><p>演练免费，可反复学习。正式出发消耗 2 树枝＋1 浆果；成功奖励 1 古代构件和好感 +10，仅一次。也可用${bag(d.care)}和平修复，奖励相同。正式事件需要守望手势。</p>${button('practice',id,'免费战术演练','',!near||e.lesson<3)}${button('battle',id,v.outpost?'✓ 据点已安定':'进入巡械据点','',!near||v.outpost||!e.tech.includes('watch'))}${button('repair',id,'交付材料和平修复','',!near||v.outpost||!e.tech.includes('watch'))}</article>`;
 body+=`<h3>聚落手艺 · 可选分支，不挡九级主线</h3><div class="co-grid">${VILLAGE_TECH.map(t=>{const reason=villageTechReason(s,t);return`<article class="co-card"><h3>${t.name} · ${t.level}级</h3><p>${t.text}<br>前置：${t.requires.map(id=>VILLAGE_TECH.find(t=>t.id===id).name).join(' → ')||'见面教学'}<br>材料：${bag(t.cost)}</p>${button('tech',id,reason||'共同研究',t.id,!near||!!reason)}${reason?'<small>'+reason+'</small>':''}</article>`;}).join('')}</div>`;
 return{title:d.name,body};
}
export function renderRoadmap(s,requirements){const missing=requirements.filter(r=>!r.ok),novice=!s.settlements.expert&&guideStage(s)<3;return `<button data-do="${novice?'guide':'growth'}" class="growth-strip-main"><b>${s.level} / 九级</b><span>${esc(novice?'先完成：'+guideGoal(s)[0]:s.level===9?'九级之后：深层远征与自由共建':missing.length?'下一级还差 '+missing.length+' 项 · '+missing[0].text:'条件齐备，前往晋升设施')}</span></button><button data-do="guide-toggle" aria-label="切换成长提示">${s.settlements.expert?'精简引导':'展开全部'}</button>`;}
export function renderGuide(s){const [title,text]=guideGoal(s);return`<h3>${title}</h3><p>${text}</p><p>当前 ${guideStage(s)+1}/4 步。演练可重复；展开全部系统可随时切换。</p>`;}
